const mem=$getWorkflowStaticData('global');
const anteriores=mem.d7Contadores || {};
const listo=mem.d7Listo === true;
const siguiente={};
let total=0;
const muestras=[];
for(const item of $input.all()) {
  const d=item.json;
  const id=String(d.query_id || d.consulta || 'desconocido');
  const filas=Number(d.filas_acumuladas || 0);
  const previo=anteriores[id];
  // Primer sondeo crea baseline. Consultas nuevas posteriores cuentan su total.
  const delta = previo === undefined ? (listo ? filas : 0) : (filas>=previo ? filas-previo : 0);
  siguiente[id]=filas;
  total += delta;
  if(delta>0) muestras.push(`${d.consulta?.slice(0,70) || id}: ${delta}`);
}
mem.d7Contadores=siguiente;
mem.d7Listo=true;
return [{json:{alerta:total>1000,filas_en_intervalo:total,detalle:muestras.slice(0,5).join(' | ')}}];

